 r['qualitativeEvidenceReview']={'frozenPacketObservations':text,'concentratedOnsetEvidenceAssessment':onset,'directImpactGroundingExplanationPresent':bool(r['v9CandidateAssessmentsWithin5']),'literalDropRejectionStatement':False,'impactBasedDemotionInference':r['within2'],'demotionInferenceLimit':'Frozen non-Drop kind plus weak/unclear impact assessment and explicit lack-of-impact rationale support an interpretation; no cross-run causal identity or hidden model reasoning established.','gameplayMomentAssessment':'Expert-reference proximity retained as an eligible semantic candidate; player interaction suitability untested.' if r['within2'] else 'No semantic event within ±5s; gameplay moment coverage missing under this descriptive rule.','waveformOrListeningEvidenceAvailable':False}
